head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldods60401_pop";

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — inqOrgnDisclsAcptNo

// [A] 초기 목록 미해결 — jldods60401_pop: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldods60401_pop.onpageload' });
    }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name grd_reportList_oncellclick
 * @description grd_reportList 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_reportList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_reportList');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_reportList */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        scwin.fnWrite(r["formCd"]); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_reportList.oncellclick' });
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name fnWrite
 * @description fn Write 처리
 * @param {String} formCd formCd
 * @returns {void}
 * @hidden N
 */
scwin.fnWrite = function (formCd) {
    const inqOrgnDisclsAcptNo = (String(((dma_pageContext.get("inqOrgnDisclsAcptNo") ?? "")) === null ? '' : ((dma_pageContext.get("inqOrgnDisclsAcptNo") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("inqOrgnDisclsAcptNo") ?? "")) === null ? '' : ((dma_pageContext.get("inqOrgnDisclsAcptNo") ?? ""))));
    const url = "/submission/disclosure.do?method=createForm&formCd=" + formCd + "&inqOrgnDisclsAcptNo=" + inqOrgnDisclsAcptNo;
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
    $c.win.setPageFrameSrc(null, (function (__u) { let __s = String(__u === null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(url));
    $c.win.closePopup();
};

/**
 * @method
 * @name goNewWrite
 * @description go New Write 처리
 * @returns {void}
 * @hidden N
 */
scwin.goNewWrite = function () {
    const url = "/discls/dsReport.do?method=searchReport";
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
    $c.win.setPageFrameSrc(null, (function (__u) { let __s = String(__u === null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(url));
    $c.win.closePopup();
};
